#!/usr/bin/env python3
"""Offline WAN telemetry incident analyzer.

Reads UTF-8 JSON Lines from stdin, writes one JSON object per line to stdout.
Solves an exact finite inference problem using Z3 (integer linear arithmetic).
"""
import sys
import json
import re
from fractions import Fraction
from math import gcd

try:
    import z3
except Exception:  # pragma: no cover
    z3 = None

NAME_RE = re.compile(r'^[A-Za-z][A-Za-z0-9_-]{0,31}$')
METRICS = {"demand", "link", "ingress", "egress"}


def is_name(x):
    return isinstance(x, str) and NAME_RE.fullmatch(x) is not None


def is_int(x):
    return type(x) is int  # excludes bool


class Invalid(Exception):
    pass


def _reject_const(x):
    raise ValueError("nonstandard constant")


def parse_line(line):
    """Return (kind, value). kind in {'malformed','json'}."""
    try:
        val = json.loads(line, parse_constant=_reject_const)
        return 'json', val
    except (ValueError, TypeError, RecursionError):
        return 'malformed', None


def validate(req):
    """Validate and normalize. Returns normalized dict or raises Invalid."""
    if not isinstance(req, dict):
        raise Invalid()
    # id
    if 'id' not in req:
        raise Invalid()
    rid = req['id']
    if not is_name(rid):
        raise Invalid()
    # version
    if not is_int(req.get('version')) or req.get('version') != 1:
        raise Invalid()

    # nodes
    nodes = req.get('nodes')
    if not isinstance(nodes, list) or not (2 <= len(nodes) <= 12):
        raise Invalid()
    for n in nodes:
        if not is_name(n):
            raise Invalid()
    if len(set(nodes)) != len(nodes):
        raise Invalid()
    nodeset = set(nodes)

    # edges
    edges = req.get('edges')
    if not isinstance(edges, list) or len(edges) > 32:
        raise Invalid()
    edge_ids = []
    edge_set = set()
    edge_index = {}
    for e in edges:
        if not isinstance(e, dict):
            raise Invalid()
        eid = e.get('id')
        if not is_name(eid):
            raise Invalid()
        if eid in edge_set:
            raise Invalid()
        s = e.get('source')
        t = e.get('target')
        if s not in nodeset or t not in nodeset or s == t:
            raise Invalid()
        cap = e.get('capacity')
        if not is_int(cap) or not (0 <= cap <= 1000000):
            raise Invalid()
        edge_index[eid] = len(edge_ids)
        edge_ids.append(eid)
        edge_set.add(eid)

    # commodities
    commodities = req.get('commodities')
    if not isinstance(commodities, list) or len(commodities) > 12:
        raise Invalid()
    comm_ids = []
    comm_set = set()
    comm_pairs = set()
    comm_data = []  # list of dict with source,target,routes (routes as list of (edges list, weight))
    for c in commodities:
        if not isinstance(c, dict):
            raise Invalid()
        cid = c.get('id')
        if not is_name(cid):
            raise Invalid()
        if cid in comm_set:
            raise Invalid()
        s = c.get('source')
        t = c.get('target')
        if s not in nodeset or t not in nodeset or s == t:
            raise Invalid()
        if (s, t) in comm_pairs:
            raise Invalid()
        routes = c.get('routes')
        if not isinstance(routes, list) or not (1 <= len(routes) <= 3):
            raise Invalid()
        parsed_routes = []
        wsum = 0
        for r in routes:
            if not isinstance(r, dict):
                raise Invalid()
            ed = r.get('edges')
            w = r.get('weight')
            if not isinstance(ed, list) or len(ed) < 1:
                raise Invalid()
            if not is_int(w) or not (1 <= w <= 8):
                raise Invalid()
            wsum += w
            # validate path
            cur = s
            visited = {s}
            for eid in ed:
                if not is_name(eid) or eid not in edge_set:
                    raise Invalid()
                ee = edges[edge_index[eid]]
                if ee['source'] != cur:
                    raise Invalid()
                cur = ee['target']
                if cur in visited:
                    raise Invalid()
                visited.add(cur)
            if cur != t:
                raise Invalid()
            parsed_routes.append((ed, w))
        if wsum > 8:
            raise Invalid()
        comm_pairs.add((s, t))
        comm_set.add(cid)
        comm_data.append({'id': cid, 'source': s, 'target': t, 'routes': parsed_routes})
        comm_ids.append(cid)

    # domains
    domains = req.get('domains')
    if not isinstance(domains, list) or len(domains) > 14:
        raise Invalid()
    for d in domains:
        if not is_name(d):
            raise Invalid()
    if len(set(domains)) != len(domains):
        raise Invalid()
    domainset = set(domains)

    # max_faults
    mf = req.get('max_faults')
    if not is_int(mf) or not (0 <= mf <= len(domains)):
        raise Invalid()

    # snapshots
    snapshots = req.get('snapshots')
    if not isinstance(snapshots, list) or not (1 <= len(snapshots) <= 4):
        raise Invalid()
    snap_ids = set()
    snap_data = []
    total_obs = 0
    nc = len(comm_ids)
    for sn in snapshots:
        if not isinstance(sn, dict):
            raise Invalid()
        sid = sn.get('id')
        if not is_name(sid) or sid in snap_ids:
            raise Invalid()
        snap_ids.add(sid)
        bounds = sn.get('bounds')
        if not isinstance(bounds, list) or len(bounds) != nc:
            raise Invalid()
        bnd = []
        for b in bounds:
            if not isinstance(b, list) or len(b) != 2:
                raise Invalid()
            lo, hi = b[0], b[1]
            if not is_int(lo) or not is_int(hi) or not (0 <= lo <= hi <= 10000):
                raise Invalid()
            bnd.append((lo, hi))
        controller = sn.get('controller')
        if not isinstance(controller, list) or len(controller) != nc:
            raise Invalid()
        for v in controller:
            if not is_int(v) or not (0 <= v <= 10000):
                raise Invalid()
        tol = sn.get('tolerance')
        if not is_int(tol) or not (0 <= tol <= 10000):
            raise Invalid()
        obs = sn.get('observations')
        if not isinstance(obs, list) or len(obs) > 96:
            raise Invalid()
        obs_ids = set()
        parsed_obs = []
        for o in obs:
            if not isinstance(o, dict):
                raise Invalid()
            oid = o.get('id')
            if not is_name(oid) or oid in obs_ids:
                raise Invalid()
            obs_ids.add(oid)
            metric = o.get('metric')
            if not isinstance(metric, str) or metric not in METRICS:
                raise Invalid()
            target = o.get('target')
            if not is_name(target):
                raise Invalid()
            if metric == 'demand':
                if target not in comm_set:
                    raise Invalid()
            elif metric == 'link':
                if target not in edge_set:
                    raise Invalid()
            else:  # ingress/egress
                if target not in nodeset:
                    raise Invalid()
            lo = o.get('lower')
            hi = o.get('upper')
            if not is_int(lo) or not is_int(hi) or not (-1000000 <= lo <= hi <= 1000000):
                raise Invalid()
            dom = o.get('domain')
            if dom is None:
                pass
            elif not is_name(dom) or dom not in domainset:
                raise Invalid()
            parsed_obs.append({'metric': metric, 'target': target, 'lo': lo, 'hi': hi, 'domain': dom})
        total_obs += len(obs)
        if total_obs > 256:
            raise Invalid()
        snap_data.append({'id': sid, 'bounds': bnd, 'controller': controller,
                          'tolerance': tol, 'observations': parsed_obs})

    return {
        'id': rid, 'nodes': nodes, 'edges': edges, 'edge_ids': edge_ids,
        'edge_index': edge_index, 'commodities': comm_data, 'comm_ids': comm_ids,
        'domains': domains, 'max_faults': mf, 'snapshots': snap_data,
    }


def lcm(a, b):
    return a // gcd(a, b) * b


def frac_str(fr):
    return "%d/%d" % (fr.numerator, fr.denominator)


def solve(req):
    if z3 is None:
        raise RuntimeError("z3 unavailable")

    nodes = req['nodes']
    edges = req['edges']
    edge_ids = req['edge_ids']
    edge_index = req['edge_index']
    commodities = req['commodities']
    comm_ids = req['comm_ids']
    domains = req['domains']
    max_faults = req['max_faults']
    snapshots = req['snapshots']

    nc = len(comm_ids)
    ne = len(edge_ids)
    ns = len(snapshots)
    nd = len(domains)

    # route weight sums W per commodity
    W = []
    for c in commodities:
        W.append(sum(w for (_, w) in c['routes']))

    L = 1
    for w in W:
        L = lcm(L, w)

    # coefficient L*(w/W) per (snapshot independent) per commodity -> dict edge_index -> coeff int
    # coeff_int[ci][eidx] = L * (sum of route weights using edge) / W[ci]
    coeff = [[0] * ne for _ in range(nc)]
    for ci, c in enumerate(commodities):
        wc = W[ci]
        for (ed, w) in c['routes']:
            # L * w / wc
            add = L * w // wc  # exact because wc | L
            for eid in ed:
                coeff[ci][edge_index[eid]] += add

    # Z3 variables
    q = [[z3.Int('q_%d_%d' % (s, ci)) for ci in range(nc)] for s in range(ns)]
    faulty = [z3.Bool('f_%d' % d) for d in range(nd)]
    domain_index = {d: i for i, d in enumerate(domains)}

    base = []
    bounds = []  # per snapshot list of (lo,hi)
    for s in range(ns):
        bnd = snapshots[s]['bounds']
        bounds.append(bnd)
        for ci in range(nc):
            lo, hi = bnd[ci]
            base.append(q[s][ci] >= lo)
            base.append(q[s][ci] <= hi)

    # capacity constraints
    for s in range(ns):
        for e in range(ne):
            cap = edges[e]['capacity']
            expr = None
            for ci in range(nc):
                cf = coeff[ci][e]
                if cf:
                    term = cf * q[s][ci]
                    expr = term if expr is None else expr + term
            if expr is None:
                continue  # 0 <= cap always (cap >= 0)
            base.append(expr <= L * cap)

    # helper value expression * L for an observation
    def value_expr_L(s, metric, target):
        if metric == 'demand':
            ci = comm_ids.index(target)
            return L * q[s][ci]
        if metric == 'link':
            e = edge_index[target]
            expr = None
            for ci in range(nc):
                cf = coeff[ci][e]
                if cf:
                    term = cf * q[s][ci]
                    expr = term if expr is None else expr + term
            if expr is None:
                return z3.IntVal(0)
            return expr
        if metric == 'ingress':
            expr = None
            for ci, c in enumerate(commodities):
                if c['source'] == target:
                    term = L * q[s][ci]
                    expr = term if expr is None else expr + term
            return expr if expr is not None else z3.IntVal(0)
        if metric == 'egress':
            expr = None
            for ci, c in enumerate(commodities):
                if c['target'] == target:
                    term = L * q[s][ci]
                    expr = term if expr is None else expr + term
            return expr if expr is not None else z3.IntVal(0)
        raise RuntimeError('bad metric')

    for s in range(ns):
        for o in snapshots[s]['observations']:
            expr = value_expr_L(s, o['metric'], o['target'])
            loL = L * o['lo']
            hiL = L * o['hi']
            inside = z3.And(expr >= loL, expr <= hiL)
            if o['domain'] is None:
                base.append(inside)
            else:
                base.append(z3.Or(inside, faulty[domain_index[o['domain']]]))

    # ---- Optimize minimum faults ----
    o = z3.Optimize()
    o.add(base)
    fault_sum = z3.Sum([z3.If(f, 1, 0) for f in faulty]) if nd > 0 else z3.IntVal(0)
    h = o.minimize(fault_sum)
    if o.check() != z3.sat:
        return {'id': req['id'], 'status': 'infeasible'}
    k = o.lower(h).as_long() if hasattr(o, 'lower') else None
    if k is None:
        # fallback
        k = o.model().eval(fault_sum).as_long()
    if k > max_faults:
        return {'id': req['id'], 'status': 'infeasible'}

    base_k = base + [fault_sum == k]

    # helper: solve sat with extra constraints
    def sat_with(extra):
        s = z3.Solver()
        s.add(base_k)
        s.add(extra)
        return s.check() == z3.sat

    def get_model(extra=None):
        s = z3.Solver()
        s.add(base_k)
        if extra is not None:
            s.add(extra)
        if s.check() != z3.sat:
            return None
        return s.model()

    # ---- ranges for demands ----
    # demands[s][ci] = (min,max)
    demand_ranges = [[(0, 0)] * nc for _ in range(ns)]
    for s in range(ns):
        for ci in range(nc):
            lo, hi = bounds[s][ci]
            if lo == hi:
                demand_ranges[s][ci] = (lo, hi)
                continue
            mn = _opt(base_k, q[s][ci], minimize=True)
            mx = _opt(base_k, q[s][ci], minimize=False)
            demand_ranges[s][ci] = (mn, mx)

    unique = all(demand_ranges[s][ci][0] == demand_ranges[s][ci][1]
                 for s in range(ns) for ci in range(nc))

    # ---- ranges for links ----
    # for each snapshot/edge: exact rational (Fraction)
    link_ranges = [[None] * ne for _ in range(ns)]
    for s in range(ns):
        for e in range(ne):
            # determine contributing commodities and if all fixed
            expr = None
            all_fixed = True
            total = Fraction(0)
            for ci in range(nc):
                cf = coeff[ci][e]
                if cf:
                    term = cf * q[s][ci]
                    expr = term if expr is None else expr + term
                    lo, hi = bounds[s][ci]
                    if lo != hi:
                        all_fixed = False
                    else:
                        total += Fraction(cf, L) * lo
            if expr is None:
                link_ranges[s][e] = (Fraction(0), Fraction(0))
                continue
            if all_fixed:
                link_ranges[s][e] = (total, total)
                continue
            mn = _opt(base_k, expr, minimize=True)
            mx = _opt(base_k, expr, minimize=False)
            link_ranges[s][e] = (Fraction(mn, L), Fraction(mx, L))

    # ---- faults possible/forced ----
    possible = []
    forced = []
    for d in range(nd):
        # possible: exists model with faulty[d] true
        if sat_with(faulty[d]):
            possible.append(domains[d])
        # forced: no model with faulty[d] false
        if not sat_with(z3.Not(faulty[d])):
            forced.append(domains[d])
    # canonicalize order follow input domains order
    poss_set = set(possible)
    forc_set = set(forced)
    possible = [d for d in domains if d in poss_set]
    forced = [d for d in domains if d in forc_set]

    # ---- witness ----
    m0 = get_model()
    w_demands = [[_model_int(m0, q[s][ci]) for ci in range(nc)] for s in range(ns)]
    # compute links & faults from q
    w_links, w_faults = _compute_derived(req, coeff, L, w_demands)

    # ---- alternative ----
    alternative = None
    if not unique:
        diff = None
        for s in range(ns):
            for ci in range(nc):
                neq = q[s][ci] != w_demands[s][ci]
                diff = neq if diff is None else z3.Or(diff, neq)
        m2 = get_model(diff)
        if m2 is None:
            alternative = None
        else:
            a_demands = [[_model_int(m2, q[s][ci]) for ci in range(nc)] for s in range(ns)]
            a_links, a_faults = _compute_derived(req, coeff, L, a_demands)
            alternative = {'demands': a_demands, 'links': _links_str(a_links), 'faults': a_faults}
            # ensure differs
            if a_demands == w_demands:
                alternative = None

    # ---- verdicts ----
    verdicts = []
    for s in range(ns):
        ctrl = snapshots[s]['controller']
        tol = snapshots[s]['tolerance']
        if nc == 0:
            agree_exists = True
            disagree_exists = False
        else:
            agree = z3.And([z3.And(q[s][ci] >= ctrl[ci] - tol, q[s][ci] <= ctrl[ci] + tol)
                            for ci in range(nc)])
            disagree = z3.Or([z3.Or(q[s][ci] < ctrl[ci] - tol, q[s][ci] > ctrl[ci] + tol)
                              for ci in range(nc)])
            agree_exists = sat_with(agree)
            disagree_exists = sat_with(disagree)
        if disagree_exists and not agree_exists:
            v = 'inconsistent'
        elif agree_exists and not disagree_exists:
            v = 'consistent'
        else:
            v = 'undetermined'
        verdicts.append(v)

    snap_out = []
    for s in range(ns):
        dem = [[demand_ranges[s][ci][0], demand_ranges[s][ci][1]] for ci in range(nc)]
        lnk = [[frac_str(link_ranges[s][e][0]), frac_str(link_ranges[s][e][1])] for e in range(ne)]
        snap_out.append({'id': snapshots[s]['id'], 'demands': dem, 'links': lnk,
                         'verdict': verdicts[s]})

    result = {
        'id': req['id'],
        'status': 'unique' if unique else 'ambiguous',
        'min_faults': k,
        'faults': {'forced': forced, 'possible': possible},
        'snapshots': snap_out,
        'witness': {'demands': w_demands, 'links': _links_str(w_links), 'faults': w_faults},
        'alternative': alternative,
    }
    return result


def _model_int(model, expr):
    v = model.eval(expr, model_completion=True)
    return v.as_long()


def _opt(base_k, expr, minimize=True):
    o = z3.Optimize()
    o.add(base_k)
    if minimize:
        h = o.minimize(expr)
    else:
        h = o.maximize(expr)
    if o.check() != z3.sat:
        raise RuntimeError('unexpected unsat in range')
    if minimize:
        val = o.lower(h)
    else:
        val = o.upper(h)
    return val.as_long()


def _compute_derived(req, coeff, L, demands):
    nodes = req['nodes']
    edges = req['edges']
    edge_ids = req['edge_ids']
    commodities = req['commodities']
    comm_ids = req['comm_ids']
    domains = req['domains']
    ns = len(req['snapshots'])
    nc = len(comm_ids)
    ne = len(edge_ids)

    links = []
    faults = set()
    for s in range(ns):
        qv = demands[s]
        loads = [Fraction(0) for _ in range(ne)]
        for ci in range(nc):
            for e in range(ne):
                cf = coeff[ci][e]
                if cf:
                    loads[e] += Fraction(cf, L) * qv[ci]
        # build metrics
        metrics = {}
        for ci in range(nc):
            metrics[('demand', comm_ids[ci])] = Fraction(qv[ci])
            c = commodities[ci]
            for (ed, w) in c['routes']:
                amt = Fraction(qv[ci] * w, sum(ww for (_, ww) in c['routes']))
            # ingress/egress
        # compute ingress/egress
        for n in nodes:
            ing = sum(qv[ci] for ci, c in enumerate(commodities) if c['source'] == n)
            egr = sum(qv[ci] for ci, c in enumerate(commodities) if c['target'] == n)
            metrics[('ingress', n)] = Fraction(ing)
            metrics[('egress', n)] = Fraction(egr)
        for e in range(ne):
            metrics[('link', edge_ids[e])] = loads[e]
        # check observations
        for o in req['snapshots'][s]['observations']:
            val = metrics[(o['metric'], o['target'])]
            if not (o['lo'] <= val <= o['hi']):
                if o['domain'] is not None:
                    faults.add(o['domain'])
        links.append(loads)
    return links, [d for d in domains if d in faults]


def _links_str(links):
    return [[frac_str(v) for v in row] for row in links]


def main():
    out = sys.stdout
    for line in sys.stdin:
        kind, val = parse_line(line)
        if kind == 'malformed':
            out.write(json.dumps({"id": None, "status": "error", "error": "malformed_json"}) + "\n")
            out.flush()
            continue
        # json ok; now validate schema
        rid = None
        try:
            # determine id for error echo
            if isinstance(val, dict) and is_name(val.get('id')):
                rid = val.get('id')
